[CmdletBinding()]
param([ValidateSet('Copy','Live')][string]$Mode='Copy',[string]$ApprovedTargetsFile)
# Operator-only repair of our NEW cohort metadata. Never changes TCNMCst,
# legacy links, assignments, approvals, receipts, bills, points, or PIN values.
$ErrorActionPreference='Stop';[Console]::InputEncoding=[Text.Encoding]::UTF8;[Console]::OutputEncoding=[Text.Encoding]::UTF8
$scope='SCCRM-HQ-MEMBER-CODES-V1';$marker='64fa3170-80ae-45ee-b9f3-7478b2a46e34'
$db=$null;$sourceDb=$null;$tx=$null;$packet=$null;$stage='packet';$builders=@()
function Refuse([string]$Code){throw $Code}
function Open([string]$Server,[string]$Database,$Credential){$b=New-Object Data.SqlClient.SqlConnectionStringBuilder;$b['Data Source']=$Server;$b['Initial Catalog']=$Database;$b['User ID']=[string]$Credential.user;$b['Password']=[string]$Credential.password;$b['Connect Timeout']=5;$b['Application Name']='SCCRM-Explicit-Cohort-Encoding-Repair';$b['Pooling']=$false;$c=New-Object Data.SqlClient.SqlConnection $b.ConnectionString;try{$c.Open();return $c}finally{$b['Password']=''}}
function Q($Connection,[string]$Sql,[hashtable]$Parameters=@{}){$q=$Connection.CreateCommand();$q.CommandTimeout=8;$q.CommandText=$Sql;if($Connection -eq $db -and $tx){$q.Transaction=$tx};foreach($k in $Parameters.Keys){$v=$Parameters[$k];if($null -eq $v){$v=[DBNull]::Value};if($k -in @('id','operation')){$p=$q.Parameters.Add('@'+$k,[Data.SqlDbType]::UniqueIdentifier)}elseif($k -in @('oldName','newName','oldEmail','newEmail')){$p=$q.Parameters.Add('@'+$k,[Data.SqlDbType]::NVarChar,200)}else{$p=$q.Parameters.Add('@'+$k,[Data.SqlDbType]::VarChar,160)};$p.Value=$v};return $q}
function Scalar($Connection,[string]$Sql,[hashtable]$Parameters=@{}){$q=Q $Connection $Sql $Parameters;try{$v=$q.ExecuteScalar();if($v -is [DBNull]){return $null};return $v}finally{$q.Dispose()}}
function Run([string]$Sql,[hashtable]$Parameters=@{}){$q=Q $db $Sql $Parameters;try{return $q.ExecuteNonQuery()}finally{$q.Dispose()}}
try{
 $raw=[Console]::In.ReadToEnd();if($raw.Length -gt 65536){Refuse 'COHORT_REPAIR_PACKET_TOO_LARGE'};$packet=$raw|ConvertFrom-Json;$raw=$null
 if($packet.scope -cne $scope -or $packet.marker -cne $marker -or $packet.reason -cne 'CONSOLE_UTF8_COHORT_REPAIR' -or ([string]$packet.operationId) -cnotmatch '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'){Refuse 'COHORT_REPAIR_PACKET_REFUSED'}
 $target=$packet.target;$members=@($packet.members);$branch=[string]$target.branch;$role=if($branch -ceq '000'){'hq'}else{'branch'};$database=[string]$target.database;$machine=[string]$target.machine;$identity=[string]$target.identity;$hq=[string]$packet.hqIdentity
 if($members.Count -lt 1 -or $members.Count -gt 2 -or $branch -cnotmatch '^(000|001|003|004|005)$' -or $target.role -cne $role -or $identity -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._:/@-]{1,159}$'){Refuse 'COHORT_REPAIR_SCOPE_REFUSED'}
 if($Mode -ceq 'Copy'){
  if($database -cne ('SCCRM_FanoutCopy_20261029_'+$branch) -or $target.server -cne 'tcp:100.90.166.72,49800' -or $machine -cne 'SERVER' -or $hq -cne ('copy000/SERVER.SQLEXPRESS/SCCRM_FanoutCopy_20261029_000/'+$marker)){Refuse 'COHORT_REPAIR_COPY_ONLY'}
  $sourceDatabase='SCCRM_FanoutCopy_20261029_000'
 }else{
  if($database -cne 'AdaAcc' -or $hq -cne ('hq000/SERVER.SQLEXPRESS/AdaAcc/'+$marker) -or !$ApprovedTargetsFile -or $members.Count -ne 2){Refuse 'COHORT_REPAIR_LIVE_APPROVAL_REQUIRED'}
  $approved=Get-Content -LiteralPath $ApprovedTargetsFile -Raw|ConvertFrom-Json
  if($approved.scope -cne $scope -or $approved.marker -cne $marker){Refuse 'COHORT_REPAIR_ALLOWLIST_REFUSED'}
  $selected=@($approved.targets|Where-Object{$_.branch -ceq $branch -and $_.role -ceq $role -and $_.identity -ceq $identity -and $_.machine -ceq $machine -and $_.server -ceq $target.server -and $_.database -ceq $database -and $_.allowProvision -eq $true})
  if($selected.Count -ne 1){Refuse 'COHORT_REPAIR_TARGET_NOT_APPROVED'};$sourceDatabase='AdaAcc'
 }
 $seen=@{};foreach($member in $members){$id=[string]$member.memberId;if($id -cnotmatch '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' -or $seen.ContainsKey($id) -or $member.previousCode -cne ('SC-'+$id.Replace('-','').Substring(0,16).ToUpperInvariant())){Refuse 'COHORT_REPAIR_MEMBER_REFUSED'};$seen[$id]=$true;foreach($p in @($member.oldProfile,$member.newProfile)){if(!$p -or !([string]$p.name).Trim() -or ([string]$p.name).Length -gt 200 -or ([string]$p.phone) -cnotmatch '^0[0-9]{9}$' -or ([string]$p.email).Length -gt 100){Refuse 'COHORT_REPAIR_PROFILE_REFUSED'}}}
 if(!$packet.admin.user -or !$packet.admin.password -or !$packet.hqAdmin.user -or !$packet.hqAdmin.password){Refuse 'COHORT_REPAIR_OPERATOR_REQUIRED'}
 $db=Open ([string]$target.server) $database $packet.admin;$sourceDb=Open 'tcp:100.90.166.72,49800' $sourceDatabase $packet.hqAdmin;$stage='identities'
 foreach($entry in @(@($db,$machine,$database,$branch,$identity,$role),@($sourceDb,'SERVER',$sourceDatabase,'000',$hq,'hq'))){
  if((Scalar $entry[0] "SET LOCK_TIMEOUT 1000;SET DEADLOCK_PRIORITY LOW;SELECT CASE WHEN CONVERT(nvarchar(128),SERVERPROPERTY('MachineName'))=@machine AND DB_NAME()=@database THEN 1 ELSE 0 END" @{machine=[string]$entry[1];database=[string]$entry[2]}) -ne 1){Refuse 'COHORT_REPAIR_SQL_IDENTITY_REFUSED'}
  if((Scalar $entry[0] "SELECT CONVERT(nvarchar(36),value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID('dbo.SCCRM_MemberCodeScope') AND name='SCCRM_MemberCodesMarker'") -cne $marker -or (Scalar $entry[0] 'SELECT COUNT(*) FROM dbo.SCCRM_MemberCodeScope WHERE singleton=1 AND marker=@marker AND scope=@scope AND hq_identity=@hq AND target_identity=@identity AND database_name=@database AND machine_name=@machine AND branch_code=@branch AND role=@role' @{marker=$marker;scope=$scope;hq=$hq;identity=[string]$entry[4];database=[string]$entry[2];machine=[string]$entry[1];branch=[string]$entry[3];role=[string]$entry[5]}) -ne 1){Refuse 'COHORT_REPAIR_SCOPE_OWNERSHIP_REFUSED'}
  if($Mode -ceq 'Copy' -and (Scalar $entry[0] "SELECT COUNT(*) FROM dbo.SCCRM_FanoutCopyMeta WHERE marker='fa35c153-6692-43b8-afd1-b102a119b002' AND scope='SCCRM-FANOUT-COPY-LAB-20261029' AND branch_code=@branch" @{branch=[string]$entry[3]}) -ne 1){Refuse 'COHORT_REPAIR_COPY_MARKER_REQUIRED'}
 }
 foreach($object in @('SCCRM_MemberCodeMigrationCohort','SCCRM_MemberCodeAssignments','SCCRM_MemberCodeApprovals','SCCRM_MemberCodeReceipts','SCCRM_MemberCodeAliases')){if((Scalar $db "SELECT CONVERT(nvarchar(36),value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID(@object) AND name='SCCRM_MemberCodesMarker'" @{object='dbo.'+$object}) -cne $marker){Refuse 'COHORT_REPAIR_OBJECT_OWNERSHIP_REFUSED'}}
 if((Scalar $sourceDb "SELECT CONVERT(nvarchar(36),value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID('dbo.SCCRM_LiveMemberLink') AND name='SCCRM_LiveSyncMarker'") -cne 'ef76cc14-1b6b-49c9-8da7-1bfaea3dd92b'){Refuse 'COHORT_REPAIR_HQ_WITNESS_OWNERSHIP_REFUSED'}
 $stage='transaction';$before=[long](Scalar $db 'SELECT COUNT_BIG(*) FROM dbo.TCNMCst');$tx=$db.BeginTransaction()
 if((Scalar $db "DECLARE @r int;EXEC @r=sys.sp_getapplock @Resource='SCCRM_MemberCodesProvision',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=1000;SELECT @r") -lt 0){Refuse 'COHORT_REPAIR_BUSY'}
 if($Mode -ceq 'Live' -and (Scalar $db 'SELECT COUNT(*) FROM dbo.SCCRM_MemberCodeMigrationCohort WITH(UPDLOCK,HOLDLOCK)') -ne 2){Refuse 'COHORT_REPAIR_LIVE_COHORT_CHANGED'}
 if($null -eq (Scalar $db "SELECT OBJECT_ID('dbo.SCCRM_MemberCodeCohortRepairAudit')")){
  $null=Run 'CREATE TABLE dbo.SCCRM_MemberCodeCohortRepairAudit(operation_id uniqueidentifier NOT NULL,member_id uniqueidentifier NOT NULL,previous_code varchar(20) NOT NULL,target_identity varchar(160) NOT NULL,old_name nvarchar(200) NOT NULL,old_phone varchar(30) NOT NULL,old_email nvarchar(100) NOT NULL,new_name nvarchar(200) NOT NULL,new_phone varchar(30) NOT NULL,new_email nvarchar(100) NOT NULL,reason varchar(80) NOT NULL,repaired_at datetime NOT NULL,PRIMARY KEY(operation_id,member_id))'
  $null=Run "EXEC sys.sp_addextendedproperty @name='SCCRM_MemberCodesMarker',@value=@marker,@level0type='SCHEMA',@level0name='dbo',@level1type='TABLE',@level1name='SCCRM_MemberCodeCohortRepairAudit'" @{marker=$marker}
 }elseif((Scalar $db "SELECT CONVERT(nvarchar(36),value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID('dbo.SCCRM_MemberCodeCohortRepairAudit','U') AND name='SCCRM_MemberCodesMarker'") -cne $marker){Refuse 'COHORT_REPAIR_UNOWNED_AUDIT_REFUSED'}
 $changed=0;$outcomes=@()
 foreach($member in $members){
  $p=@{operation=[guid]$packet.operationId;id=[guid]$member.memberId;code=[string]$member.previousCode;identity=$identity;oldName=[string]$member.oldProfile.name;oldPhone=[string]$member.oldProfile.phone;oldEmail=[string]$member.oldProfile.email;newName=[string]$member.newProfile.name;newPhone=[string]$member.newProfile.phone;newEmail=[string]$member.newProfile.email}
  foreach($table in @('Assignments','Approvals','Receipts','Aliases')){if((Scalar $db ('SELECT COUNT(*) FROM dbo.SCCRM_MemberCode'+$table+' WITH(UPDLOCK,HOLDLOCK) WHERE member_id=@id') $p) -ne 0){Refuse 'COHORT_REPAIR_ASSIGNMENT_ALREADY_EXISTS'}}
  if((Scalar $sourceDb "SELECT COUNT(*) FROM dbo.SCCRM_LiveMemberLink l JOIN dbo.TCNMCst c ON c.FTCstCode=l.ada_code WHERE l.member_id=@id AND l.ada_code=@code AND c.FTBchCode='000' AND c.FTWhoIns='SCCRM_SYNC_CREATE' AND CONVERT(varbinary(max),l.profile_name)=CONVERT(varbinary(max),@newName) AND CONVERT(varbinary(max),l.profile_phone)=CONVERT(varbinary(max),@newPhone) AND CONVERT(varbinary(max),ISNULL(l.profile_email,N''))=CONVERT(varbinary(max),@newEmail) AND CONVERT(varbinary(max),CONVERT(nvarchar(200),c.FTCstName))=CONVERT(varbinary(max),@newName) AND CONVERT(varbinary(max),ISNULL(c.FTCstTel,''))=CONVERT(varbinary(max),@newPhone) AND CONVERT(varbinary(max),CONVERT(nvarchar(100),ISNULL(c.FTCstEmail,'')))=CONVERT(varbinary(max),@newEmail)" $p) -ne 1){Refuse 'COHORT_REPAIR_FRESH_HQ_WITNESS_MISMATCH'}
  if((Scalar $db 'SELECT COUNT(*) FROM dbo.SCCRM_MemberCodeCohortRepairAudit WHERE operation_id=@operation AND member_id=@id AND previous_code=@code AND target_identity=@identity AND CONVERT(varbinary(max),old_name)=CONVERT(varbinary(max),@oldName) AND CONVERT(varbinary(max),old_phone)=CONVERT(varbinary(max),@oldPhone) AND CONVERT(varbinary(max),old_email)=CONVERT(varbinary(max),@oldEmail) AND CONVERT(varbinary(max),new_name)=CONVERT(varbinary(max),@newName) AND CONVERT(varbinary(max),new_phone)=CONVERT(varbinary(max),@newPhone) AND CONVERT(varbinary(max),new_email)=CONVERT(varbinary(max),@newEmail)' $p) -eq 1){
   if((Scalar $db 'SELECT COUNT(*) FROM dbo.SCCRM_MemberCodeMigrationCohort WHERE member_id=@id AND previous_code=@code AND CONVERT(varbinary(max),profile_name)=CONVERT(varbinary(max),@newName) AND CONVERT(varbinary(max),profile_phone)=CONVERT(varbinary(max),@newPhone) AND CONVERT(varbinary(max),profile_email)=CONVERT(varbinary(max),@newEmail)' $p) -ne 1){Refuse 'COHORT_REPAIR_REPLAY_CHANGED'};$outcomes+=@{previousCode=$member.previousCode;outcome='already_repaired'};continue
  }
  if((Scalar $db 'SELECT COUNT(*) FROM dbo.SCCRM_MemberCodeMigrationCohort WITH(UPDLOCK,HOLDLOCK) WHERE member_id=@id AND previous_code=@code AND CONVERT(varbinary(max),profile_name)=CONVERT(varbinary(max),@oldName) AND CONVERT(varbinary(max),profile_phone)=CONVERT(varbinary(max),@oldPhone) AND CONVERT(varbinary(max),profile_email)=CONVERT(varbinary(max),@oldEmail)' $p) -ne 1){Refuse 'COHORT_REPAIR_OLD_TUPLE_CHANGED'}
  $null=Run 'INSERT dbo.SCCRM_MemberCodeCohortRepairAudit(operation_id,member_id,previous_code,target_identity,old_name,old_phone,old_email,new_name,new_phone,new_email,reason,repaired_at) VALUES(@operation,@id,@code,@identity,@oldName,@oldPhone,@oldEmail,@newName,@newPhone,@newEmail,''CONSOLE_UTF8_COHORT_REPAIR'',GETUTCDATE())' $p
  if((Run 'UPDATE dbo.SCCRM_MemberCodeMigrationCohort SET profile_name=@newName,profile_phone=@newPhone,profile_email=@newEmail WHERE member_id=@id AND previous_code=@code AND CONVERT(varbinary(max),profile_name)=CONVERT(varbinary(max),@oldName) AND CONVERT(varbinary(max),profile_phone)=CONVERT(varbinary(max),@oldPhone) AND CONVERT(varbinary(max),profile_email)=CONVERT(varbinary(max),@oldEmail)' $p) -ne 1){Refuse 'COHORT_REPAIR_WRITE_NOT_CONFIRMED'}
  $changed++;$outcomes+=@{previousCode=$member.previousCode;outcome='repaired_metadata_only'}
 }
 $tx.Commit();$tx.Dispose();$tx=$null;$after=[long](Scalar $db 'SELECT COUNT_BIG(*) FROM dbo.TCNMCst')
 [ordered]@{ok=$true;scope=$scope;mode=$Mode;branch=$branch;operationId=$packet.operationId;metadataRowsChanged=$changed;members=$outcomes;customerRowsWritten=0;customerCountBefore=$before;customerCountAfter=$after;pinRead=$false}|ConvertTo-Json -Depth 5 -Compress
}catch{
 if($tx){try{$tx.Rollback()}catch{}};$base=$_.Exception.GetBaseException();$code=if($base.Message -cmatch '^[A-Z][A-Z0-9_]{5,100}$'){$base.Message}else{'COHORT_REPAIR_OPERATION_FAILED'}
 [ordered]@{ok=$false;mode=$Mode;stage=$stage;code=$code;sqlNumber=if($base -is [Data.SqlClient.SqlException]){$base.Number}else{$null};errorType=$base.GetType().Name;customerRowsWritten=0;detailsWithheld=$true;pinRead=$false}|ConvertTo-Json -Compress;exit 1
}finally{if($tx){$tx.Dispose()};if($sourceDb){$sourceDb.Dispose()};if($db){$db.Dispose()};if($packet){if($packet.admin){$packet.admin.password=$null};if($packet.hqAdmin){$packet.hqAdmin.password=$null}};$packet=$null}
